     {
         var result = _formatter.GenerateSlug("Hello World");

         Assert.AreEqual("hello-world", result);
     }

     [TestMethod]
     public void GenerateSlug_TitleWithSpecialChars_ContainsOnlySlugChars()
     {
         var result = _formatter.GenerateSlug("C# Is Great!");

         Assert.MatchesRegex(@"^[a-z0-9\-]+$", result);
     }

     [TestMethod]
     public void GenerateSlug_TitleStartingWithLetters_StartsWithExpectedWord()
     {
         var result = _formatter.GenerateSlug("MSTest Is Awesome");

         Assert.StartsWith("mstest", result);
     }

     [TestMethod]
     public void GenerateSlug_TitleEndingWithWord_EndsWithExpectedWord()
     {
         var result = _formatter.GenerateSlug("Unit Testing Rocks");

         Assert.EndsWith("rocks", result);
     }

     [TestMethod]
     public void GenerateSlug_TitleWithMultipleSpaces_DoesNotContainSpaces()
     {
         var result = _formatter.GenerateSlug("  lots   of   spaces  ");

         Assert.DoesNotContain(" ", result);
     }

     [TestMethod]
     [DataRow("")]
     [DataRow("   ")]
     public void GenerateSlug_WhiteSpace_ThrowsArgumentException(string title)
     {
         Assert.ThrowsExactly<ArgumentException>(() => _formatter.GenerateSlug(title));
     }

     [TestMethod]
     public void GenerateSlug_Null_ThrowsArgumentNullException()
     {
         Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.GenerateSlug(null!));
     }

